package android.content;import java.io.*;import java.util.*;import java.util.concurrent.*;import android.content.pm.*;import android.content.res.*;public class Context{
public static final int MODE_PRIVATE=0;public static final String WINDOW_SERVICE="window",ACCESSIBILITY_SERVICE="accessibility",NOTIFICATION_SERVICE="notification",POWER_SERVICE="power",ACTIVITY_SERVICE="activity",CLIPBOARD_SERVICE="clipboard";
private final SharedPreferences prefs=new SharedPreferences();private final ContentResolver resolver=new ContentResolver();public PackageManager pm=new PackageManager();public final Map<String,Object> services=new HashMap<>();public int foregroundStarts,serviceStops,activityStarts;public boolean activityStartFailure;
public Context getApplicationContext(){return this;}public String getPackageName(){return "org.adguardian.app";}public PackageManager getPackageManager(){return pm;}public AssetManager getAssets(){return new AssetManager();}public Resources getResources(){return new Resources();}public ContentResolver getContentResolver(){return resolver;}public Object getSystemService(String n){return services.get(n);}public File getFilesDir(){File f=new File(System.getProperty("java.io.tmpdir"),"adguardian-host-tests");f.mkdirs();return f;}public File getCacheDir(){File f=new File(getFilesDir(),"cache");f.mkdirs();return f;}public SharedPreferences getSharedPreferences(String n,int m){return prefs;}public Executor getMainExecutor(){return Runnable::run;}public ComponentName startForegroundService(Intent i){foregroundStarts++;return new ComponentName(getPackageName(),i.target.getName());}public boolean stopService(Intent i){serviceStops++;return true;}public void startActivity(Intent i){activityStarts++;if(activityStartFailure)throw new IllegalStateException("settings entry unavailable");}public int checkSelfPermission(String p){return PackageManager.PERMISSION_GRANTED;}}
